<?php $b=$booking; $canManage=in_array($role,['admin','dispatcher'],true); ?>
<section class="panel"><div class="heading-row"><h2><?= esc($b['service_name']) ?></h2><span class="badge"><?= esc($b['status']) ?></span></div><dl class="detail-grid"><div><dt>Customer</dt><dd><?= esc($customer['display_name']??'Account unavailable') ?></dd></div><div><dt>Preferred time</dt><dd><?= esc($b['preferred_at']) ?></dd></div><div><dt>Confirmed visit</dt><dd><?= esc($b['scheduled_at']??'Awaiting review') ?><?= $b['scheduled_end']?' — '.esc($b['scheduled_end']):'' ?></dd></div><div><dt>Assigned technician</dt><dd><?= esc($technician['display_name']??'Not assigned') ?></dd></div><div><dt>Address</dt><dd><?= esc($b['address']) ?></dd></div><div><dt>Customer contact</dt><dd><?= esc($customer['profile']['contact_number']??'') ?></dd></div></dl><h3>Request notes</h3><p class="pre-line"><?= esc($b['notes']?:'No additional notes.') ?></p></section>
<?php if(($role==='customer'||$canManage)&&in_array($b['status'],['requested','scheduled'],true)): ?><section class="panel"><h2>Change this request</h2><form class="inline-form" action="<?= site_url('bookings/'.$b['id'].'/change') ?>" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="reschedule"><label>New preferred time<input type="datetime-local" name="preferred_at" required></label><button type="submit">Request reschedule</button></form><p class="muted">Rescheduling returns the booking to review and cancels its current assignment.</p><form action="<?= site_url('bookings/'.$b['id'].'/change') ?>" method="post" data-confirm="Cancel this booking and its current assignment?"><?= csrf_field() ?><input type="hidden" name="action" value="cancel"><button class="secondary" type="submit">Cancel booking</button></form></section><?php endif ?>
<?php if($canManage&&in_array($b['status'],['requested','scheduled'],true)): ?><section class="panel"><h2>Schedule & assign</h2><p>Each visit reserves a two-hour technician slot. Overlapping assignments are blocked.</p><?php if(!$technicians): ?><p>No active technician accounts. An administrator must assign the technician role to an employee first.</p><?php else: ?><form action="<?= site_url('bookings/'.$b['id'].'/assign') ?>" method="post"><?= csrf_field() ?><label for="technician_user_id">Technician</label><select name="technician_user_id" id="technician_user_id" required><?php foreach($technicians as $tech): ?><option value="<?= (int)$tech['id'] ?>"><?= esc($tech['display_name']) ?> · user #<?= (int)$tech['id'] ?></option><?php endforeach ?></select><label for="scheduled_at">Confirmed start (Philippine time)</label><input type="datetime-local" id="scheduled_at" name="scheduled_at" required><button type="submit">Confirm schedule & assignment</button></form><?php endif ?></section><?php endif ?>
<?php if($role==='technician'&&$b['assignment_status']!=='cancelled'): ?><section class="panel"><h2>Site attendance</h2><p>GPS location is requested only when you press check in. If permission is denied or location is unavailable, use the manual option and explain why.</p>
<?php if(!$attendance&&$b['status']==='scheduled'): ?><form class="gps-checkin" action="<?= site_url('assignments/'.$b['assignment_id'].'/attendance') ?>" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="checkin"><input type="hidden" name="latitude"><input type="hidden" name="longitude"><button class="gps-button" type="button">Check in with GPS</button><p class="gps-status" role="status" aria-live="polite"></p><details><summary>Location unavailable? Record a manual check-in</summary><label>Reason<textarea name="manual_reason" minlength="10" maxlength="500" rows="3"></textarea></label><button type="submit" name="manual" value="1">Submit manual check-in</button></details></form><?php endif ?>
<?php if($attendance): ?><p>Checked in: <?= esc($attendance['checked_in_at']) ?> · <?= $attendance['latitude']!==null?'GPS recorded':'Manual location exception' ?></p><?php if(!$attendance['checked_out_at']): ?><form action="<?= site_url('assignments/'.$b['assignment_id'].'/attendance') ?>" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="checkout"><button class="secondary" type="submit">Check out</button></form><?php else: ?><p>Checked out: <?= esc($attendance['checked_out_at']) ?></p><?php endif ?><?php endif ?></section>
<?php if($attendance&&!$report&&$b['status']==='in_progress'): ?><section class="panel"><h2>Complete this job</h2><form action="<?= site_url('assignments/'.$b['assignment_id'].'/report') ?>" method="post" data-confirm="Submit this report and mark the booking completed?"><?= csrf_field() ?><label for="report">Service report</label><textarea id="report" name="report" minlength="10" maxlength="5000" rows="6" required></textarea><button type="submit">Submit report & complete service</button></form></section><?php endif ?>
<section class="panel"><h2>Report an equipment issue</h2><form action="<?= site_url('assignments/'.$b['assignment_id'].'/issue') ?>" method="post"><?= csrf_field() ?><label for="description">Describe the problem</label><textarea id="description" name="description" minlength="10" maxlength="3000" required rows="4"></textarea><button class="secondary" type="submit">Report issue</button></form></section><?php endif ?>
<?php if($attendance&&$canManage): ?><section class="panel"><h2>Attendance record</h2><p>Technician: <?= esc($technician['display_name']??'') ?> · user #<?= (int)$attendance['technician_user_id'] ?></p><p>Check-in <?= esc($attendance['checked_in_at']) ?> · Check-out <?= esc($attendance['checked_out_at']??'Not recorded') ?></p><p><?= $attendance['latitude']!==null?'Coordinates: '.esc($attendance['latitude']).', '.esc($attendance['longitude']):'Manual exception: '.esc($attendance['manual_reason']) ?></p></section><?php endif ?>
<?php if($report): ?><section class="panel"><h2>Completed service report</h2><p class="pre-line"><?= esc($report['report']) ?></p><small><?= esc($report['created_at']) ?></small></section><?php endif ?>
<?php if(in_array($role,['admin','customer'],true)): ?><section class="panel"><h2>Payment records</h2><?php if(!$payments): ?><p>No payments have been recorded for this booking.</p><?php endif ?><?php foreach($payments as $payment): ?><p><a href="<?= site_url('receipts/'.$payment['id']) ?>">Receipt #<?= (int)$payment['id'] ?></a> · PHP <?= number_format((float)$payment['amount'],2) ?> · <?= esc($payment['reference']) ?></p><?php endforeach ?>
<?php if($role==='admin'): ?><details><summary>Record a received payment</summary><p>Record only a payment actually received. This form does not charge a card or transfer funds.</p><form action="<?= site_url('bookings/'.$b['id'].'/payment') ?>" method="post"><?= csrf_field() ?><label>Amount (PHP)<input name="amount" type="number" min="0.01" step="0.01" required></label><label>Unique payment reference<input name="reference" maxlength="100" required></label><button type="submit">Save payment record</button></form></details><?php endif ?></section><?php endif ?>
